const overseasScenes=[{"id": "singapore-demo", "country": "Singapore", "title": "Device demonstration", "description": "A visitor explores the VR headset and handheld controller at a healthcare exhibition.", "width": 1600, "height": 1200}, {"id": "singapore-experience", "country": "Singapore", "title": "Hands-on VR experience", "description": "An on-site participant tries the headset beside the cognitive assessment and rehabilitation display.", "width": 1600, "height": 1200}, {"id": "indonesia-demo", "country": "Indonesia", "title": "Guided product demonstration", "description": "A visitor tries a QuickMind headset with assistance at the YIWEI Medical exhibition stand.", "width": 1200, "height": 1600}, {"id": "indonesia-team", "country": "Indonesia", "title": "On-site product introduction", "description": "The team guides a visitor through the VR setup and accompanying software.", "width": 800, "height": 1066}, {"id": "hong-kong-community", "country": "Hong Kong", "title": "Community cognitive assessment", "description": "An assisted VR session in a community setting, as documented in YIWEI Medical’s overseas deployment materials.", "width": 1600, "height": 1200}, {"id": "hong-kong-service", "country": "Hong Kong", "title": "Assisted community session", "description": "Staff help participants fit the VR headset during a community assessment activity.", "width": 702, "height": 939}];
let sceneCountry='All';
function sceneCard(s){return `<figure class="scene-card"><a href="/assets/scenarios/${s.id}.webp" target="_blank" rel="noopener" aria-label="View full photograph: ${s.country}, ${s.title}"><img src="/assets/scenarios/${s.id}.webp" width="${s.width}" height="${s.height}" alt="${s.country}: ${s.description}" loading="lazy" decoding="async"><span class="scene-zoom">View full photo ↗</span></a><figcaption><span class="eyebrow">${s.country}</span><h3>${s.title}</h3><p>${s.description}</p></figcaption></figure>`}
function overseasPreview(){return `<section class="section container" id="international-scenes">${sectionTitle('QUICKMIND AROUND THE WORLD','See the experience in real settings.','Photographs from Singapore and Indonesia demonstrations and Hong Kong community sessions.')}<div class="scene-grid">${[overseasScenes[0],overseasScenes[2],overseasScenes[4]].map(sceneCard).join('')}</div><div class="buttons"><a class="btn outline" href="/pages/international-scenes/" data-route>Explore International Scenes</a><button class="text-link" data-action="clinic">Arrange a Product Demo</button></div></section>`}
function overseasPage(){return `<section class="page-intro"><span class="eyebrow">INTERNATIONAL SCENES</span><h1>Experience QuickMind.<br>See it in context.</h1><p>Explore YIWEI Medical’s overseas product demonstrations and community sessions, with photographs from Singapore, Indonesia and Hong Kong.</p></section><section class="container section"><div class="filter-bar" aria-label="Filter photographs by location">${['All','Singapore','Indonesia','Hong Kong'].map(c=>`<button class="filter ${sceneCountry===c?'selected':''}" data-scene-country="${c}" aria-pressed="${sceneCountry===c}">${c==='All'?'All locations':c}</button>`).join('')}</div><div class="scene-grid">${overseasScenes.filter(s=>sceneCountry==='All'||s.country===sceneCountry).map(sceneCard).join('')}</div><p class="fine">Company-supplied photographs document demonstrations and use settings. Product configurations vary by setting and market. These scenes do not establish clinical outcomes or the contents of the proposed Home Plan.</p><div class="evidence-panel"><div><span class="eyebrow">YOUR NEXT STEP</span><h2>Explore your local setup.</h2><p>Ask about the appropriate configuration, local availability, onboarding and commercial terms for your home, clinic or organization.</p><div class="buttons"><button class="btn" data-action="inquiry">Request a Quote</button><button class="text-link" data-action="distributor">Discuss Distribution</button></div></div><div class="research-note"><h3>Review the product documentation</h3><p>Explore the research and market-specific records alongside the real-world photographs.</p><div class="buttons"><a class="text-link" href="/pages/clinical-evidence/" data-route>Clinical Evidence</a><a class="text-link" href="/pages/registrations/" data-route>Registration Documents</a></div></div></div></section>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-scene-country]');if(b){sceneCountry=b.dataset.sceneCountry;render(false)}});
